"use client";

import { useState } from "react";
import { Search, Filter, Calendar, FileText, Activity, X } from "lucide-react";

const initialPatients = [
  { id: "UHID-9921", name: "Emily Rodriguez", age: 34, gender: "F", bloodGroup: "O+", lastVisit: "2026-09-01", condition: "Appendectomy Recovery", phone: "+1 555-0192" },
  { id: "UHID-8472", name: "Sarah Jenkins", age: 58, gender: "F", bloodGroup: "A-", lastVisit: "2026-09-03", condition: "Hypertension", phone: "+1 555-0184" },
  { id: "UHID-1039", name: "Michael Chen", age: 42, gender: "M", bloodGroup: "B+", lastVisit: "2026-09-03", condition: "GERD", phone: "+1 555-0173" },
];

export default function GlobalPatientDirectory() {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedPatient, setSelectedPatient] = useState<typeof initialPatients[0] | null>(null);

  // Dynamic filtering based on search input
  const filteredPatients = initialPatients.filter((pt) => 
    pt.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    pt.id.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="max-w-7xl mx-auto space-y-6 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Patient Directory</h1>
          <p className="text-sm text-slate-500">Centralized database of all registered patients.</p>
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-200 bg-slate-50 flex gap-4">
          <div className="relative flex-1">
            <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 transform -translate-y-1/2" />
            <input 
              type="text" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by UHID or Name..." 
              className="w-full pl-9 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-brand-500"
            />
          </div>
          <button className="flex items-center px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors">
            <Filter className="w-4 h-4 mr-2" /> Filters
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-slate-600">
            <thead className="bg-white border-b border-slate-200 text-slate-500 uppercase text-xs font-semibold">
              <tr>
                <th className="px-6 py-4">UHID</th>
                <th className="px-6 py-4">Patient Profile</th>
                <th className="px-6 py-4">Medical Details</th>
                <th className="px-6 py-4">Last Visit</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 bg-white">
              {filteredPatients.map((pt) => (
                <tr key={pt.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 font-bold text-slate-900">{pt.id}</td>
                  <td className="px-6 py-4">
                    <div className="font-medium text-brand-700">{pt.name}</div>
                    <div className="text-xs text-slate-500">{pt.age} yrs • {pt.gender}</div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="inline-flex items-center px-2 py-1 rounded-md text-xs font-medium bg-red-50 text-red-700 mb-1">
                      {pt.bloodGroup}
                    </span>
                    <div className="text-xs text-slate-600">{pt.condition}</div>
                  </td>
                  <td className="px-6 py-4 flex items-center text-slate-500 mt-2">
                    <Calendar className="w-3 h-3 mr-1.5" /> {pt.lastVisit}
                  </td>
                  <td className="px-6 py-4 text-right space-x-2">
                    <button 
                      onClick={() => setSelectedPatient(pt)}
                      className="p-2 text-brand-600 hover:bg-brand-50 rounded-lg transition-colors" 
                      title="View Medical History"
                    >
                      <Activity className="w-4 h-4 inline" />
                    </button>
                    <button className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors" title="View EMR">
                      <FileText className="w-4 h-4 inline" />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredPatients.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-slate-500">No patients found matching "{searchQuery}"</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Patient Details Modal */}
      {selectedPatient && (
        <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden">
            <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center">
              <h2 className="text-lg font-bold text-slate-900">Patient Overview</h2>
              <button onClick={() => setSelectedPatient(null)} className="text-slate-400 hover:text-slate-600">
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="p-6 space-y-4">
              <div className="flex justify-between border-b border-slate-100 pb-4">
                <div>
                  <div className="text-2xl font-bold text-slate-900">{selectedPatient.name}</div>
                  <div className="text-sm text-slate-500">{selectedPatient.id} • {selectedPatient.phone}</div>
                </div>
                <div className="text-right">
                  <div className="text-sm font-semibold text-red-600 text-xl">{selectedPatient.bloodGroup}</div>
                  <div className="text-xs text-slate-500">Blood Group</div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <span className="block text-xs font-semibold text-slate-400 uppercase">Current Condition</span>
                  <span className="font-medium text-slate-700">{selectedPatient.condition}</span>
                </div>
                <div>
                  <span className="block text-xs font-semibold text-slate-400 uppercase">Last Visit Date</span>
                  <span className="font-medium text-slate-700">{selectedPatient.lastVisit}</span>
                </div>
              </div>
              <button className="w-full mt-4 py-2 bg-brand-50 text-brand-700 font-semibold rounded-lg hover:bg-brand-100 transition-colors">
                Open Full EMR File
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}